'use client';
import { useState } from 'react';
import { X, Calendar, User, MapPin, CreditCard, CheckCircle } from 'lucide-react';

export default function BookingModal({ isOpen, onClose, service }) {
  const [step, setStep] = useState(1); // 1: Details, 2: Confirmation
  const [formData, setFormData] = useState({
    name: '',
    age: '',
    gender: 'Male',
    date: '',
    time: '',
    address: 'Mumbai, 400001', // Pre-filled for demo
  });

  if (!isOpen || !service) return null;

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const calculateTotal = () => {
    // Basic logic: If discountPrice exists use it, else use price
    return service.discountPrice || service.price || 0;
  };

  const handleBooking = async (e) => {
    e.preventDefault();
    try {
        const response = await fetch('http://localhost:5000/api/bookings', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                ...formData,
                serviceName: service.name,
                price: calculateTotal()
            })
        });

        if (response.ok) {
            setStep(2);
        } else {
            alert('Booking failed. Please try again.');
        }
    } catch (error) {
        console.error('Booking error:', error);
        alert('Something went wrong.');
    }
  };

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 2000,
      background: 'rgba(15, 23, 42, 0.9)', backdropFilter: 'blur(8px)',
      display: 'flex', alignItems: 'center', justifyContent: 'center'
    }}>
      <div className="glass" style={{
        width: '100%', maxWidth: '600px', padding: '2rem',
        position: 'relative', margin: '20px', borderRadius: '24px',
        border: '1px solid rgba(255, 255, 255, 0.1)',
        maxHeight: '90vh', overflowY: 'auto'
      }}>
        <button onClick={onClose} style={{
          position: 'absolute', top: '20px', right: '20px',
          background: 'transparent', border: 'none', color: 'var(--text-muted)', cursor: 'pointer'
        }}>
          <X size={24} />
        </button>

        {step === 1 ? (
            <div className="animate-fade-in">
                <h2 style={{ fontSize: '1.8rem', marginBottom: '0.5rem' }}>Confirm Booking</h2>
                <p style={{ color: 'var(--text-muted)', marginBottom: '2rem' }}>You are booking: <span style={{ color: 'var(--primary)' }}>{service.name}</span></p>
                
                <form onSubmit={handleBooking}>
                    {/* Patient Details */}
                    <div style={{ marginBottom: '1.5rem' }}>
                        <h3 style={{ fontSize: '1.1rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
                            <User size={18} /> Patient Details
                        </h3>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                            <input 
                                type="text" name="name" placeholder="Full Name" required
                                value={formData.name} onChange={handleChange}
                                style={inputStyle}
                            />
                            <div style={{ display: 'flex', gap: '1rem' }}>
                                <input 
                                    type="number" name="age" placeholder="Age" required
                                    value={formData.age} onChange={handleChange}
                                    style={inputStyle}
                                />
                                <select 
                                    name="gender" 
                                    value={formData.gender} onChange={handleChange}
                                    style={inputStyle}
                                >
                                    <option value="Male">Male</option>
                                    <option value="Female">Female</option>
                                    <option value="Other">Other</option>
                                </select>
                            </div>
                        </div>
                    </div>

                    {/* Schedule */}
                    <div style={{ marginBottom: '1.5rem' }}>
                        <h3 style={{ fontSize: '1.1rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
                            <Calendar size={18} /> Schedule
                        </h3>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                            <input 
                                type="date" name="date" required
                                value={formData.date} onChange={handleChange}
                                style={inputStyle}
                            />
                            <select name="time" style={inputStyle} required value={formData.time} onChange={handleChange}>
                                <option value="">Select Time</option>
                                <option value="09:00 AM">09:00 AM</option>
                                <option value="11:00 AM">11:00 AM</option>
                                <option value="02:00 PM">02:00 PM</option>
                                <option value="05:00 PM">05:00 PM</option>
                            </select>
                        </div>
                    </div>

                     {/* Address */}
                     <div style={{ marginBottom: '1.5rem' }}>
                        <h3 style={{ fontSize: '1.1rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '8px' }}>
                            <MapPin size={18} /> Address (Home Collection)
                        </h3>
                        <textarea 
                            name="address" rows="2" required
                            value={formData.address} onChange={handleChange}
                            style={{ ...inputStyle, resize: 'none' }}
                        />
                    </div>

                    {/* Payment Summary */}
                    <div style={{ marginBottom: '2rem', background: 'rgba(255,255,255,0.05)', padding: '1rem', borderRadius: '12px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem', color: 'var(--text-muted)' }}>
                            <span>Service Total</span>
                            <span>₹{service.price}</span>
                        </div>
                        {service.discountPrice && (
                             <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem', color: 'var(--accent)' }}>
                                <span>Discount</span>
                                <span>- ₹{service.price - service.discountPrice}</span>
                            </div>
                        )}
                         <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '1rem', borderTop: '1px solid rgba(255,255,255,0.1)', paddingTop: '1rem', fontWeight: 'bold', fontSize: '1.2rem' }}>
                            <span>Total Payable</span>
                            <span>₹{calculateTotal()}</span>
                        </div>
                    </div>

                    <button type="submit" className="btn btn-primary" style={{ width: '100%' }}>
                        Proceed to Pay ₹{calculateTotal()}
                    </button>
                    
                </form>
            </div>
        ) : (
            <div className="animate-fade-in" style={{ textAlign: 'center', padding: '2rem 0' }}>
                <CheckCircle size={64} color="var(--primary)" style={{ marginBottom: '1.5rem' }} />
                <h2 style={{ fontSize: '2rem', marginBottom: '1rem' }}>Booking Confirmed!</h2>
                <p style={{ color: 'var(--text-muted)', marginBottom: '2rem' }}>
                    Your appointment for {service.name} has been scheduled for {formData.date} at {formData.time}.
                </p>
                <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
                     <button className="btn btn-outline" onClick={onClose}>Close</button>
                     <button className="btn btn-primary" onClick={onClose}>View Bookings</button>
                </div>
            </div>
        )}
      </div>
    </div>
  );
}

const inputStyle = {
    width: '100%',
    padding: '0.8rem',
    borderRadius: '10px',
    background: 'rgba(255, 255, 255, 0.05)',
    border: '1px solid rgba(255,255,255,0.1)',
    color: '#fff',
    outline: 'none',
    fontSize: '1rem'
};
