'use client';
import { useState, useEffect, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import Navbar from '@/components/Navbar';
import BookingModal from '@/components/BookingModal';
import { Search, MapPin, Star, Filter } from 'lucide-react';

const MOCK_HOSPITALS = [
  { 
    id: 1, 
    name: 'Grand City Hospital', 
    location: 'Andheri West, Mumbai', 
    rating: 4.8, 
    discount: 'Up to 40% OFF', 
    discountValue: 40,
    distance: '2.5 km', 
    image: 'linear-gradient(45deg, #1e293b, #0f172a)', 
    price: 500, 
    discountPrice: 300,
    specialties: ['Cardiac', 'Physiotherapy', 'General Physician', 'Orthopedic']
  },
  { 
    id: 2, 
    name: 'Apex Multi-Specialty', 
    location: 'Bandra, Mumbai', 
    rating: 4.5, 
    discount: 'Flat 20% OFF', 
    discountValue: 20,
    distance: '5.0 km', 
    image: 'linear-gradient(45deg, #334155, #1e293b)', 
    price: 800, 
    discountPrice: 640,
    specialties: ['Dermatology', 'Dentist', 'Neurology'] 
  },
  { 
    id: 3, 
    name: 'City Care Centre', 
    location: 'Juhu, Mumbai', 
    rating: 4.2, 
    discount: '15% OFF on OPD', 
    discountValue: 15,
    distance: '1.2 km', 
    image: 'linear-gradient(45deg, #475569, #334155)', 
    price: 400, 
    discountPrice: 340,
    specialties: ['General Physician', 'Pediatric', 'Physiotherapy']
  },
  { 
    id: 4, 
    name: 'Global Health Institute', 
    location: 'Goregaon, Mumbai', 
    rating: 4.9, 
    discount: 'Free First Consult', 
    discountValue: 100, // Conceptually high for sorting
    distance: '8.0 km', 
    image: 'linear-gradient(45deg, #0f172a, #1e293b)', 
    price: 1000, 
    discountPrice: 0,
    specialties: ['Cardiac', 'Neurology', 'Orthopedic', 'Oncology']
  },
];

function HospitalsContent() {
  const searchParams = useSearchParams();
  const specialtyFilter = searchParams.get('specialty');
  
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHospital, setSelectedHospital] = useState(null);

  // Filter and Sort Logic
  const filteredHospitals = MOCK_HOSPITALS
    .filter(h => {
        const matchesSearch = h.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                              h.location.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesSpecialty = specialtyFilter ? h.specialties.includes(specialtyFilter) : true;
        return matchesSearch && matchesSpecialty;
    })
    .sort((a, b) => b.discountValue - a.discountValue); // Sort by Highest Discount

  return (
    <main style={{ paddingBottom: '100px' }}>
      <Navbar />
      
      <div className="container" style={{ paddingTop: 'calc(var(--header-height) + 2rem)' }}>
        
        {/* Header & Search */}
        <div style={{ marginBottom: '2rem' }}>
          <h1 style={{ marginBottom: '1rem' }}>
            {specialtyFilter ? `Top Ranked ${specialtyFilter} Hospitals` : 'Find Hospitals'}
          </h1>
          
          {specialtyFilter && (
            <p style={{ color: 'var(--primary)', marginBottom: '1rem', display: 'flex', gap: '8px', alignItems: 'center' }}>
                <Filter size={16} /> Sorted by Highest Discounts First
            </p>
          )}

          <div className="glass" style={{ display: 'flex', gap: '1rem', padding: '1rem', alignItems: 'center' }}>
             <MapPin size={20} color="var(--primary)" />
             <input 
                type="text"
                placeholder="Search by hospital name or location..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                style={{ background: 'transparent', border: 'none', color: '#fff', fontSize: '1rem', outline: 'none', flex: 1 }}
             />
             <button className="btn btn-primary">Search</button>
          </div>
        </div>

        {/* Listings */}
        <div className="grid-cards">
          {filteredHospitals.map((hospital) => (
             <div key={hospital.id} className="glass" style={{ padding: '0', overflow: 'hidden', cursor: 'pointer', transition: 'transform 0.2s' }}>
                <div style={{ height: '200px', background: hospital.image, position: 'relative' }}>
                   <div style={{ position: 'absolute', top: '10px', left: '10px', background: 'rgba(0,0,0,0.6)', color: '#fff', padding: '4px 8px', borderRadius: '6px', fontSize: '0.8rem', display: 'flex', alignItems: 'center', gap: '4px' }}>
                      <Star size={12} fill="#fbbf24" stroke="none" /> {hospital.rating}
                   </div>
                   {specialtyFilter && (
                       <div style={{ position: 'absolute', bottom: '10px', right: '10px', background: 'var(--primary)', color: '#fff', padding: '4px 10px', borderRadius: '20px', fontSize: '0.8rem', fontWeight: 'bold' }}>
                           {hospital.discountValue}% OFF
                       </div>
                   )}
                </div>
                
                <div style={{ padding: '1.5rem' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                        <h3 style={{ fontSize: '1.3rem' }}>{hospital.name}</h3>
                    </div>
                    
                    <p style={{ color: 'var(--text-muted)', fontSize: '0.9rem', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '6px' }}>
                       <MapPin size={14} /> {hospital.location} • {hospital.distance}
                    </p>

                    {/* Show relevant specialty tag if filtered */}
                     <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '1rem' }}>
                        {hospital.specialties.slice(0, 3).map(s => (
                            <span key={s} style={{ 
                                fontSize: '0.75rem', 
                                padding: '2px 8px', 
                                borderRadius: '4px', 
                                background: s === specialtyFilter ? 'rgba(0, 210, 211, 0.2)' : 'rgba(255,255,255,0.05)',
                                color: s === specialtyFilter ? 'var(--primary)' : 'var(--text-muted)',
                                border: s === specialtyFilter ? '1px solid var(--primary)' : 'none'
                            }}>
                                {s}
                            </span>
                        ))}
                     </div>

                    <div style={{ background: 'rgba(255, 159, 67, 0.1)', color: 'var(--accent)', padding: '10px', borderRadius: '8px', marginBottom: '1.5rem', textAlign: 'center', fontWeight: 'bold', fontSize: '0.95rem' }}>
                        {hospital.discount}
                    </div>

                    <div style={{ display: 'flex', gap: '1rem' }}>
                        <button className="btn btn-outline" style={{ flex: 1 }}>Details</button>
                        <button 
                            className="btn btn-primary" 
                            style={{ flex: 1 }}
                            onClick={() => setSelectedHospital(hospital)}
                        >
                            Book Now
                        </button>
                    </div>
                </div>
             </div>
          ))}
        </div>
        
        {filteredHospitals.length === 0 && (
            <div style={{ textAlign: 'center', padding: '4rem', color: 'var(--text-muted)' }}>
                <h3>No hospitals found for this criteria.</h3>
                <p>Try searching for a different location or service.</p>
            </div>
        )}

      </div>

      <BookingModal 
        isOpen={!!selectedHospital} 
        onClose={() => setSelectedHospital(null)} 
        service={selectedHospital} 
      />
    </main>
  );
}

export default function Hospitals() {
  return (
    <Suspense fallback={<div className="container" style={{ paddingTop: '100px' }}>Loading...</div>}>
      <HospitalsContent />
    </Suspense>
  );
}
